#include <string>

class Solution {
public:
    int minimumTimeToInitialState(std::string word, int k) {
        int n = word.size();
        for (int t = 1; t * k < n; ++t) {
            if (word.substr(t * k) == word.substr(0, n - t * k)) {
                return t;
            }
        }
        return (n + k - 1) / k;
    }
};

class Solution {
    public int minimumTimeToInitialState(String word, int k) {
        int n = word.length();
        for (int t = 1; t * k < n; ++t) {
            if (word.startsWith(word.substring(t * k))) {
                return t;
            }
        }
        return (n + k - 1) / k;
    }
}

var minimumTimeToInitialState = function(word, k) {
    const n = word.length;
    for (let t = 1; t * k < n; ++t) {
        if (word.startsWith(word.slice(t * k))) {
            return t;
        }
    }
    return Math.floor((n + k - 1) / k);
